            <style>
            .cad-drop{display:flex;min-height:122px;align-items:center;justify-content:center;padding:18px;border:2px dashed #cbd5e1;border-radius:12px;background:rgba(248,250,252,.7);text-align:center;cursor:pointer}.cad-drop.dragging{border-color:#6366f1;background:rgba(99,102,241,.08)}.cad-drop strong{display:block;margin-bottom:7px;color:#334155}.cad-drop small{color:#64748b}.cad-toolbar{display:flex;flex-wrap:wrap;gap:9px;margin-top:14px}.cad-status{min-height:21px;color:#64748b;font-size:13px}.cad-status.error{color:#b91c1c}.cad-status.success{color:#047857}.cad-canvas-wrap{position:relative;min-height:520px;overflow:hidden;border:1px solid #dbe3ef;border-radius:12px;background:#f8fafc;touch-action:none}.cad-canvas-wrap.dark{background:#0b1220;border-color:#334155}.cad-canvas{display:block;width:100%;height:520px;cursor:grab}.cad-canvas.dragging{cursor:grabbing}.cad-empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;text-align:center;color:#64748b;pointer-events:none}.cad-empty[hidden]{display:none}.cad-info{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}.cad-info span{padding:5px 9px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:13px}.cad-tip{margin:13px 0 0;color:#64748b;font-size:13px}@media(max-width:640px){.cad-canvas-wrap,.cad-canvas{min-height:390px;height:390px}.cad-toolbar button{flex:1}}
            </style>
            <section class="tool-panel">
                <label class="cad-drop" id="dropZone" for="file"><span><strong>点击选择或拖放 DXF 图纸</strong><small>支持 ASCII DXF，单个文件不超过 20 MB；图纸只在浏览器中解析</small></span></label>
                <input id="file" type="file" accept=".dxf,application/dxf,text/plain" hidden>
                <div class="cad-toolbar"><button class="btn" id="zoomIn" type="button" disabled>放大</button><button class="btn" id="zoomOut" type="button" disabled>缩小</button><button class="btn" id="fit" type="button" disabled>适应图纸</button><button class="btn secondary" id="toggleBg" type="button" disabled>切换深色背景</button></div>
                <p class="cad-status" id="status" role="status">支持直线、圆、圆弧、轻量多段线、普通多段线及基础文字。DWG 请先在 CAD 软件中另存为 ASCII DXF。</p>
            </section>
            <section class="tool-panel"><div class="cad-info" id="info"></div><div class="cad-canvas-wrap" id="canvasWrap"><canvas class="cad-canvas" id="canvas" aria-label="CAD 图纸预览区域"></canvas><div class="cad-empty" id="empty">选择 DXF 图纸后，可用鼠标滚轮缩放并拖动查看。</div></div><p class="cad-tip">说明：复杂块参照、填充、外部参照、专用字体与 DWG 文件可能无法完整显示；本工具仅用于快速预览，不替代专业 CAD 软件。</p></section>
            <script>
            (()=>{'use strict';const MAX_FILE_BYTES=20*1024*1024,MAX_ENTITIES=200000,$=id=>document.getElementById(id),canvas=$('canvas'),wrap=$('canvasWrap'),ctx=canvas.getContext('2d');let entities=[],bounds=null,scale=1,panX=0,panY=0,dark=false,drag=null;function status(message,type=''){const node=$('status');node.textContent=message;node.className='cad-status '+type;}function num(value){const n=Number(value);return Number.isFinite(n)?n:0;}function groupMap(groups){const map=new Map();groups.forEach(([code,value])=>{const list=map.get(code)||[];list.push(value);map.set(code,list);});return map;}function one(map,code,index=0){return (map.get(code)||[])[index];}function parseDxf(text){const raw=text.replace(/^\uFEFF/,'').split(/\r?\n/),pairs=[];for(let i=0;i+1<raw.length;i+=2){const code=Number(raw[i].trim());if(Number.isFinite(code))pairs.push([code,raw[i+1].trimEnd()]);}let section='',records=[],current=null;for(let i=0;i<pairs.length;i++){const [code,value]=pairs[i];if(code===0&&value==='SECTION'){section=pairs[i+1]?.[0]===2?pairs[++i][1]:'';continue;}if(code===0&&value==='ENDSEC'){if(current)records.push(current);section='';current=null;continue;}if(section!=='ENTITIES')continue;if(code===0){if(current)records.push(current);current={type:value,groups:[]};}else if(current)current.groups.push([code,value]);}if(current)records.push(current);const output=[];for(let i=0;i<records.length&&output.length<MAX_ENTITIES;i++){const record=records[i],map=groupMap(record.groups),type=record.type;if(type==='LINE')output.push({type:'line',x1:num(one(map,10)),y1:num(one(map,20)),x2:num(one(map,11)),y2:num(one(map,21))});else if(type==='CIRCLE')output.push({type:'circle',x:num(one(map,10)),y:num(one(map,20)),r:Math.abs(num(one(map,40)))});else if(type==='ARC')output.push({type:'arc',x:num(one(map,10)),y:num(one(map,20)),r:Math.abs(num(one(map,40))),start:num(one(map,50)),end:num(one(map,51))});else if(type==='LWPOLYLINE'){const xs=map.get(10)||[],ys=map.get(20)||[],points=xs.map((x,index)=>[num(x),num(ys[index])]);if(points.length>1)output.push({type:'poly',points,closed:(num(one(map,70))&1)===1});}else if(type==='POLYLINE'){const points=[];while(records[i+1]?.type==='VERTEX'){const vertex=groupMap(records[++i].groups);points.push([num(one(vertex,10)),num(one(vertex,20))]);}if(records[i+1]?.type==='SEQEND')i++;if(points.length>1)output.push({type:'poly',points,closed:(num(one(map,70))&1)===1});}else if(type==='TEXT'||type==='MTEXT'){const textValue=(map.get(1)||[]).concat(map.get(3)||[]).join('').replace(/\\P/g,' ');if(textValue)output.push({type:'text',x:num(one(map,10)),y:num(one(map,20)),height:Math.max(1,num(one(map,40))||8),angle:num(one(map,50)),text:textValue.slice(0,500)});}if(output.length>=MAX_ENTITIES)throw new Error('图元数量超过 '+MAX_ENTITIES+'，请使用专业 CAD 软件打开。');}if(!output.length)throw new Error('没有找到可预览的二维图元，请确认文件是 ASCII DXF。');return output;}function getBounds(items){let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const add=(x,y)=>{minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);};items.forEach(item=>{if(item.type==='line'){add(item.x1,item.y1);add(item.x2,item.y2);}else if(item.type==='circle'||item.type==='arc'){add(item.x-item.r,item.y-item.r);add(item.x+item.r,item.y+item.r);}else if(item.type==='poly')item.points.forEach(point=>add(point[0],point[1]));else if(item.type==='text')add(item.x,item.y);});if(!Number.isFinite(minX))return null;return {minX,minY,maxX,maxY,width:Math.max(1,maxX-minX),height:Math.max(1,maxY-minY)};}function resize(){const rect=wrap.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));canvas.style.width=rect.width+'px';canvas.style.height=rect.height+'px';draw();}function fit(){if(!bounds)return;const rect=wrap.getBoundingClientRect(),padding=28;scale=Math.max(.0001,Math.min((rect.width-padding*2)/bounds.width,(rect.height-padding*2)/bounds.height));panX=rect.width/2-(bounds.minX+bounds.width/2)*scale;panY=rect.height/2+(bounds.minY+bounds.height/2)*scale;draw();}function draw(){const rect=wrap.getBoundingClientRect(),dpr=canvas.width/Math.max(1,rect.width);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle=dark?'#0b1220':'#f8fafc';ctx.fillRect(0,0,rect.width,rect.height);if(!entities.length)return;ctx.save();ctx.translate(panX,panY);ctx.scale(scale,-scale);ctx.strokeStyle=dark?'#e2e8f0':'#1e293b';ctx.fillStyle=dark?'#e2e8f0':'#1e293b';ctx.lineWidth=Math.max(.25,1/scale);entities.forEach(item=>{ctx.beginPath();if(item.type==='line'){ctx.moveTo(item.x1,item.y1);ctx.lineTo(item.x2,item.y2);ctx.stroke();}else if(item.type==='circle'){ctx.arc(item.x,item.y,item.r,0,Math.PI*2);ctx.stroke();}else if(item.type==='arc'){ctx.arc(item.x,item.y,item.r,item.start*Math.PI/180,item.end*Math.PI/180);ctx.stroke();}else if(item.type==='poly'){ctx.moveTo(item.points[0][0],item.points[0][1]);item.points.slice(1).forEach(point=>ctx.lineTo(point[0],point[1]));if(item.closed)ctx.closePath();ctx.stroke();}else if(item.type==='text'){ctx.save();ctx.translate(item.x,item.y);ctx.rotate(-item.angle*Math.PI/180);ctx.scale(1/scale,-1/scale);ctx.font=Math.max(10,Math.min(60,item.height*scale))+'px sans-serif';ctx.fillText(item.text,0,0);ctx.restore();}});ctx.restore();}function zoomAt(factor,x,y){if(!entities.length)return;const next=Math.min(100000,Math.max(.000001,scale*factor)),worldX=(x-panX)/scale,worldY=(panY-y)/scale;scale=next;panX=x-worldX*scale;panY=y+worldY*scale;draw();}function showInfo(file){const box=$('info');box.replaceChildren();[['文件',file.name],['大小',(file.size/1024/1024).toFixed(2)+' MB'],['图元',entities.length],['范围',bounds.width.toFixed(2)+' × '+bounds.height.toFixed(2)]].forEach(([label,value])=>{const item=document.createElement('span');item.textContent=label+'：'+value;box.appendChild(item);});}async function load(file){if(!file)return;if(file.size>MAX_FILE_BYTES){status('DXF 文件不能超过 20 MB。','error');return;}if(!/\.dxf$/i.test(file.name)){status('请选择 .dxf 文件。DWG 请先另存为 ASCII DXF。','error');return;}try{status('正在本地解析图纸…');const text=await file.text();if(/AutoCAD Binary DXF/i.test(text.slice(0,128)))throw new Error('暂不支持二进制 DXF，请导出为 ASCII DXF。');entities=parseDxf(text);bounds=getBounds(entities);if(!bounds)throw new Error('图纸没有有效范围。');$('empty').hidden=true;['zoomIn','zoomOut','fit','toggleBg'].forEach(id=>$(id).disabled=false);showInfo(file);resize();fit();status('图纸已载入，可滚轮缩放、按住鼠标左键拖动查看。','success');}catch(error){entities=[];bounds=null;$('empty').hidden=false;draw();status(error.message||'图纸解析失败。','error');}}$('file').addEventListener('change',event=>load(event.target.files[0]));['dragenter','dragover'].forEach(name=>$('dropZone').addEventListener(name,event=>{event.preventDefault();$('dropZone').classList.add('dragging');}));['dragleave','drop'].forEach(name=>$('dropZone').addEventListener(name,event=>{event.preventDefault();$('dropZone').classList.remove('dragging');}));$('dropZone').addEventListener('drop',event=>load(event.dataTransfer.files[0]));$('zoomIn').addEventListener('click',()=>zoomAt(1.25,wrap.clientWidth/2,wrap.clientHeight/2));$('zoomOut').addEventListener('click',()=>zoomAt(.8,wrap.clientWidth/2,wrap.clientHeight/2));$('fit').addEventListener('click',fit);$('toggleBg').addEventListener('click',()=>{dark=!dark;wrap.classList.toggle('dark',dark);$('toggleBg').textContent=dark?'切换浅色背景':'切换深色背景';draw();});canvas.addEventListener('wheel',event=>{if(!entities.length)return;event.preventDefault();const rect=canvas.getBoundingClientRect();zoomAt(event.deltaY<0?1.15:1/1.15,event.clientX-rect.left,event.clientY-rect.top);},{passive:false});canvas.addEventListener('pointerdown',event=>{if(!entities.length)return;canvas.setPointerCapture(event.pointerId);drag={id:event.pointerId,x:event.clientX,y:event.clientY};canvas.classList.add('dragging');});canvas.addEventListener('pointermove',event=>{if(!drag||drag.id!==event.pointerId)return;panX+=event.clientX-drag.x;panY+=event.clientY-drag.y;drag.x=event.clientX;drag.y=event.clientY;draw();});['pointerup','pointercancel'].forEach(name=>canvas.addEventListener(name,event=>{if(drag?.id===event.pointerId){drag=null;canvas.classList.remove('dragging');}}));new ResizeObserver(resize).observe(wrap);resize();})();
            </script>
